mapper.select:
WITH res AS ( SELECT c.*, CASE WHEN c.deleted THEN NULL ELSE c.details END AS details, ( SELECT COUNT(*) FROM comments WHERE parent_id = c.id ) AS child_count FROM public.comments c WHERE c.reference_type = CAST(#{referenceType} AS comment_reference_type) AND c.reference_id = #{id} AND c.parent_id IS NULL ORDER BY c.created_at DESC
LIMIT #{limit}
) SELECT * FROM res ORDER BY created_at ASC

SELECT (
    SELECT 1
    FROM public.comments c
    JOIN auth.users u ON c.users_id = u.id
    WHERE c.id = #{id}
    AND u.email = #{email}
) AS exists;
